const { upload } = require('/workspace/src/upload.js');

// Fake stream + fake blobstore client to verify behavior.
const { Readable } = require('stream');
const stream = Readable.from(['hello ', 'world']);

const io = {
  putObject(obj) { throw new Error('putObject should not be called'); },
  putObjectStream(s) {
    // verify it receives the same readable stream, not a buffer
    return s.constructor.name === 'Readable'
      ? Promise.resolve('streamed')
      : Promise.reject(new Error('expected a Readable'));
  },
};

upload(io, stream).then((r) => {
  console.log('result:', r);
  if (r !== 'streamed') process.exit(1);
  console.log('OK: streaming upload used, no buffering');
}).catch((e) => { console.error(e); process.exit(1); });
"

